# Authentication Patterns

I help you implement secure authentication.

## JWT Authentication
```typescript
import jwt from 'jsonwebtoken';

function generateTokens(userId: string) {
  const accessToken = jwt.sign(
    { sub: userId },
    process.env.JWT_SECRET!,
    { expiresIn: '15m' }
  );

  const refreshToken = jwt.sign(
    { sub: userId },
    process.env.JWT_REFRESH_SECRET!,
    { expiresIn: '7d' }
  );

  return { accessToken, refreshToken };
}

function verifyToken(token: string) {
  return jwt.verify(token, process.env.JWT_SECRET!) as { sub: string };
}
```

## Password Hashing
```typescript
import bcrypt from 'bcryptjs';

async function hashPassword(password: string): Promise<string> {
  return bcrypt.hash(password, 12);
}

async function verifyPassword(password: string, hash: string): Promise<boolean> {
  return bcrypt.compare(password, hash);
}
```

## Refresh Token Flow
```typescript
async function refreshAccessToken(refreshToken: string) {
  const payload = jwt.verify(refreshToken, process.env.JWT_REFRESH_SECRET!);

  // Verify refresh token is valid in database
  const storedToken = await db.refreshToken.findUnique({
    where: { token: refreshToken },
  });

  if (!storedToken || storedToken.revoked) {
    throw new UnauthorizedError();
  }

  // Generate new tokens
  return generateTokens(payload.sub);
}
```

# Error Handling Best Practices

I help you implement robust error handling.

## Custom Error Classes
```typescript
export class AppError extends Error {
  constructor(
    message: string,
    public statusCode: number = 500,
    public code: string = 'INTERNAL_ERROR',
  ) {
    super(message);
    this.name = 'AppError';
  }
}

export class NotFoundError extends AppError {
  constructor(resource: string) {
    super(`${resource} not found`, 404, 'NOT_FOUND');
  }
}

export class ValidationError extends AppError {
  constructor(message: string) {
    super(message, 422, 'VALIDATION_ERROR');
  }
}
```

## Global Error Handler (NestJS)
```typescript
@Catch()
export class GlobalExceptionFilter implements ExceptionFilter {
  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse();

    const { status, body } = this.getErrorResponse(exception);

    response.status(status).json(body);
  }

  private getErrorResponse(exception: unknown) {
    if (exception instanceof AppError) {
      return {
        status: exception.statusCode,
        body: {
          error: exception.code,
          message: exception.message,
        },
      };
    }
    return {
      status: 500,
      body: { error: 'INTERNAL_ERROR', message: 'Something went wrong' },
    };
  }
}
```

# Vitest Unit Testing

