## Basic Tests
```typescript
import { describe, it, expect, vi } from 'vitest';

describe('UserService', () => {
  it('should create a user', async () => {
    const result = await userService.create({
      email: 'test@example.com',
    });

    expect(result).toMatchObject({
      email: 'test@example.com',
