# tRPC Type-Safe APIs

I help you build type-safe APIs with tRPC.

## Server Router
```typescript
import { initTRPC } from '@trpc/server';
import { z } from 'zod';

const t = initTRPC.create();

export const appRouter = t.router({
  user: t.router({
    getById: t.procedure
      .input(z.object({ id: z.string() }))
      .query(async ({ input }) => {
        return db.user.findUnique({ where: { id: input.id } });
      }),

    create: t.procedure
      .input(z.object({
        email: z.string().email(),
        name: z.string().optional(),
      }))
      .mutation(async ({ input }) => {
        return db.user.create({ data: input });
      }),
  }),
});

export type AppRouter = typeof appRouter;
```

## Client Usage
```tsx
import { trpc } from '@/utils/trpc';

function UserProfile({ id }: { id: string }) {
  const { data, isLoading } = trpc.user.getById.useQuery({ id });

  const createUser = trpc.user.create.useMutation({
    onSuccess: () => {
      utils.user.invalidate();
    },
  });

  if (isLoading) return <Spinner />;
  return <div>{data?.name}</div>;
}
```

## Benefits
- End-to-end type safety
- No code generation
- Full autocomplete
- Automatic validation

# GraphQL API Development

I help you build GraphQL APIs.

## Schema Definition
```graphql
type User {
  id: ID!
  email: String!
  name: String
  posts: [Post!]!
}

type Post {
  id: ID!
  title: String!
  content: String
  author: User!
}

type Query {
  user(id: ID!): User
  users: [User!]!
  post(id: ID!): Post
}

type Mutation {
  createUser(input: CreateUserInput!): User!
  createPost(input: CreatePostInput!): Post!
}

input CreateUserInput {
  email: String!
  name: String
}
```

## Resolvers (NestJS)
```typescript
@Resolver(() => User)
export class UserResolver {
  constructor(private userService: UserService) {}

  @Query(() => User, { nullable: true })
  async user(@Args('id') id: string) {
    return this.userService.findById(id);
  }

  @ResolveField(() => [Post])
  async posts(@Parent() user: User) {
    return this.postService.findByUserId(user.id);
  }

  @Mutation(() => User)
  async createUser(@Args('input') input: CreateUserInput) {
    return this.userService.create(input);
  }
}
```

# Socket.io Real-time

I help you build real-time features with Socket.io.

## Server Setup (NestJS)
```typescript
@WebSocketGateway({
  cors: { origin: '*' },
})
export class ChatGateway {
  @WebSocketServer()
  server: Server;

  @SubscribeMessage('message')
  handleMessage(@MessageBody() data: { room: string; text: string }) {
    this.server.to(data.room).emit('message', {
      text: data.text,
      timestamp: new Date(),
    });
  }

  @SubscribeMessage('join')
  handleJoin(@ConnectedSocket() client: Socket, @MessageBody() room: string) {
    client.join(room);
    return { event: 'joined', room };
  }
}
```

## Client Setup (React)
```tsx
import { io, Socket } from 'socket.io-client';

function useSocket() {
  const [socket, setSocket] = useState<Socket | null>(null);

  useEffect(() => {
    const s = io('http://localhost:3000');
    setSocket(s);

    return () => { s.disconnect(); };
  }, []);

  return socket;
}

function Chat({ room }: { room: string }) {
  const socket = useSocket();
  const [messages, setMessages] = useState<Message[]>([]);

  useEffect(() => {
    if (!socket) return;

    socket.emit('join', room);
    socket.on('message', (msg) => setMessages((prev) => [...prev, msg]));

    return () => { socket.off('message'); };
  }, [socket, room]);

  const sendMessage = (text: string) => {
    socket?.emit('message', { room, text });
  };

  return /* render chat UI */;
}
```

